import logging
from abc import ABCMeta, abstractmethod
from taf.internal.managedobject import ManagedObject, ManagedGroup
from taf.internal.core import partial_format
from taf.internal.execution.base import ExecutionError
import six
import glob
import os
import re
import time
from .exception import ExecutionsError

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class Finder(object):
    """
    Finds input file paths.
    """

    @abstractmethod
    def find(self):
        """
         Return file paths

        :return:
        """


class Mapper(object):
    """
    Map input file paths to output file paths.
    """

    @abstractmethod
    def map(self, input_file):
        """
        Maps an input file path to an output file path.

        :param str input_file: path of an input file for a FileConverter

        :returns: output file path
        :rtype: str
        """


class FilePatternFinder(Finder):
    """
    Find file paths based on input file pattern.
    """

    def __init__(self, file_path_pattern, **kwargs):
        """
        :param file_path_pattern: file paths (wildcards allowed, eg: x/y/z/*.pcap or x/*/z/*.pcap ).
        """
        super(FilePatternFinder, self).__init__(**kwargs)
        self._file_path_pattern = os.path.join(
            re.sub(r"[\[|\]]", r"[\g<0>]", os.path.dirname(file_path_pattern)),
            os.path.basename(file_path_pattern))

    def find(self):
        """
        Return file paths.

        :returns: file paths
        :rtype: iterator
        """
        return self._glob(self._file_path_pattern)

    @staticmethod
    def _glob(pattern):
        return glob.iglob(pattern)


class OutputFileMapper(Mapper):
    """
    Map input file paths to output file paths.
    """

    def __init__(self, output_extension, **kwargs):
        super(OutputFileMapper, self).__init__(**kwargs)
        self._output_extension = output_extension

    def map(self, input_file):
        """
        Maps an input file path to an output file path.

        :param str input_file: path of an input file for a FileConverter

        :returns: output file path
        :rtype: str
        """
        input_file_name = os.path.splitext(input_file)[0]
        output_file = input_file_name + self._output_extension
        return output_file


class OutputPathMapper(Mapper):
    """
    Map input file name {basename}{input_extension} to output file path
    {output_directory}/{basename}{output_extension} (input_extension and output_extension includes
    leading dot).
    """

    def __init__(self, output_directory, output_extension, **kwargs):
        super(OutputPathMapper, self).__init__(**kwargs)
        self._output_directory = output_directory
        self._output_extension = output_extension

    def map(self, input_file):
        """
        Maps an input file path to an output file path.

        :param str input_file: path of an input file for a Converter

        :returns: output file path
        :rtype: str
        """
        file_path = os.path.splitext(input_file)[0]
        file_name = os.path.basename(file_path)
        output_file = os.path.join(self._output_directory, file_name + self._output_extension)
        return output_file


@six.add_metaclass(ABCMeta)
class ConverterComponent(object):
    """
    A ConverterComponent can either be a single converter object or a group of Converter
    components.
    """

    @abstractmethod
    def convert(self):
        """
        Implementation for file conversion done in the inherited class

        :return:
        """


class NToNConverterObject(ManagedObject, ConverterComponent):
    """
    Convert a set of files.
    """

    def __init__(self, finder, mapper, command_template, executor, timeout=None, **kwargs):
        """
        Create a file converter.

        :param Finder finder: find input file paths
        :param Mapper  mapper: map each input file path to an output file path
        :param str  command_template: command template with '{input_file}' and '{output_file}'
        :param Executor  executor: tool_executor for command execution
        :param float timeout:(optional) no-activity timeout value for callable (in seconds), by
                             default no timeout configured
       """
        super(NToNConverterObject, self).__init__(**kwargs)
        self._finder = finder
        self._mapper = mapper
        self._command_template = command_template
        self._timeout = timeout
        self._executor = executor
        self._errors = {}

    def convert(self):
        """
        Convert input files to output files.
        """
        processes = []
        for input_file in self._finder.find():
            command = partial_format(
                self._command_template,
                input_file=input_file,
                output_file=self._mapper.map(input_file)).encode('utf-8')
            process = self._executor.start(command)
            logger.debug('process started for: {}'.format(command))
            processes.append(process)
        for process in processes:
            self._verify_non_zero_exit(process)
        if self._errors:
            raise ExecutionsError(errors=self._errors)

    def _verify_non_zero_exit(self, process):
        logger.debug("Checking execution status for command: {}".format(process.command))
        start_time = time.time()
        stdout = process.stdout.read(timeout=self.get_timeout_value(start_time))
        stderr = process.stderr.read(timeout=self.get_timeout_value(start_time))
        process.wait(timeout=self.get_timeout_value(start_time))
        exit_status = process.exit_status
        if exit_status or stderr:
            self._errors[process.command] = ExecutionError(
                stdout=stdout,
                stderr=stderr,
                exit_status=exit_status)
        logger.debug(
            "stdout={stdout!r}, stderr={stderr!r}, exit_status={exit_status!r}".format(
                stdout=stdout,
                stderr=stderr,
                exit_status=exit_status))

    def get_timeout_value(self, start_time):
        if self._timeout:
            time_elapsed = time.time() - start_time
            return self._timeout - time_elapsed if (time_elapsed < self._timeout) else 0.01
        else:
            return None


class ConverterGroup(ManagedGroup, ConverterComponent):
    """
        Creates a Converter Group

    """

    def convert(self):
        for member in self._members:
            member.convert()
